/* Comedy Commandos — J-Styles / Chairman's Last Call (guest-safe roster expansion)
   Wrestling silhouette, folding chair feints, grapples, stunner-inspired slapstick impact.
   Fictional, non-graphic cartoon combat. Does not grant owner Godkey permissions. */
(function(){
'use strict';
if(typeof roster==='undefined'||typeof game==='undefined'||typeof action!=='function')return;
const ID='jstyles';
if(byId[ID])return;
const fighter={id:ID,name:'J-Styles',faction:'RUC',role:'Chairman of the Ring',color:'#f34866',special:'FOLDING CHAIR FEINT',finisher:"CHAIRMAN'S LAST CALL",line:'THE CHAIRMAN HAS SPOKEN!'};
roster.push(fighter);byId[ID]=fighter;
FIGHT_STYLES[ID]={name:'Chair-Fu Power Wrestling',speed:.92,jump:.85,reach:1.18,power:1.17,route:['lowkick','punch','lowkick'],combo:'Chair Lock Three-Piece',effect:'stun',bonus:9,weapon:'Folding Chair',powerName:'Chairman Shock',stanceName:'No-Sell Grapple',archetype:'grappler',weaponType:'chair',tech:'grab'};
SUPER_ART[ID]={symbol:'♜',theme:'steel',caption:"CHAIRMAN'S LAST CALL",trait:'guardbreak',reach:55,bonus:12};
const arts=window.__CC_WEAPON_TEST__?.profiles;
if(arts)arts[ID]={weapon:'Steel Folding Chair',power:'Chairman Shockwave',stance:'No-Sell Grapple',archetype:'grappler',tech:'grab',prop:'chair',reach:1.18,damage:1.09,combo:'D→A→D',pose:'punch'};
// Local sprites make J-Styles fully illustrated; no generic rectangle / stick figure.
EMBEDDED_ASSETS['jstyles_0']='data:image/webp;base64,';
EMBEDDED_ASSETS['jstyles_1']='data:image/webp;base64,';
EMBEDDED_ASSETS['jstyles_2']='data:image/webp;base64,';
EMBEDDED_ASSETS['jstyles_3']='data:image/webp;base64,';
for(let i=0;i<4;i++){
 const picture=new Image();picture.decoding='async';picture.src=EMBEDDED_ASSETS[`${ID}_${i}`];sprites[`${ID}_${i}`]=picture;
}
const originalAction=action;
action=function(side,kind){
 const actor=game?.teams?.[side],who=actor&&activeWho(actor),opponent=actor&&game.teams[1-side];
 if(who?.id===ID&&kind==='finish'&&opponent&&Math.abs(actor.x-opponent.x)>370){
  announce('GET CLOSE FOR CHAIRMAN’S LAST CALL!',.9);sfx('block');return;
 }
 const before=actor?.attack;originalAction(side,kind);
 if(who?.id!==ID||!actor||!actor.attack||actor.attack===before)return;
 const move=actor.attack;
 if(kind==='special'){
  move.jChairSpecial=true;move.reach=Math.max(move.reach,305);move.duration=.92;move.start=.26;move.end=.48;move.damage=Math.max(move.damage,30);move.power=75;move.profile='stun';
  announce('J-STYLES • CHAIR CHECK!',1.0);
 }
 if(kind==='finish'){
  move.jChairFinisher=true;move.reach=Math.max(275,move.reach);move.damage=Math.max(79,move.damage);move.duration=1.64;move.start=.94;move.end=1.19;move.power=105;move.profile='guardbreak';
  actor.cooldown=1.32;actor.jChairCue=0;
  if(cinematic){cinematic.total=cinematic.left=2.85;cinematic.x=(actor.x+opponent.x)/2;cinematic.kind='finish';}
  cameraMode='low';cameraPulse=1.6;shake=10;flash=.19;
  announce('CHAIRMAN’S LAST CALL!',1.5);sfx('special');
 }
};
const originalRegister=registerHit;
registerHit=function(actor,opponent,move){
 if(activeWho(actor)?.id===ID&&move?.jChairFinisher){
  opponent.block=false; // signature grappling move breaks ordinary standing guard
  actor.face=opponent.x>actor.x?1:-1;
  const sign=actor.face;
  actor.x=Math.max(100,Math.min(W-100,opponent.x-sign*70));
  originalRegister(actor,opponent,move);
  if(move.didHit){
   opponent.stun=Math.max(opponent.stun,1.0);opponent.vy=-390;opponent.y=Math.min(opponent.y,-38);
   spawnRing(opponent.x,FLOOR+opponent.y-130,'#ff526f',94);
   spawnBurst(opponent.x,FLOOR+opponent.y-120,'#ffd95f',46);
   cameraMode='orbit';shake=24;flash=.55;hitStop=.2;
   announce('CHAIRMAN’S LAST CALL • K.O. IMPACT!',1.35);
   sfx('finish');buzz(120);
  }
  return;
 }
 if(activeWho(actor)?.id===ID&&move?.jChairSpecial){
  originalRegister(actor,opponent,move);
  if(move.didHit){opponent.stun=Math.max(opponent.stun,.58);opponent.x=Math.max(96,Math.min(W-96,opponent.x+actor.face*68));spawnRing(opponent.x,FLOOR-155,'#fb9bb3',40);}
  return;
 }
 originalRegister(actor,opponent,move);
};
const originalUpdate=updateFight;
updateFight=function(dt){
 if(state==='fight'&&game?.roundState==='fight')for(const actor of game.teams){
  if(activeWho(actor)?.id!==ID||!actor.attack?.jChairFinisher)continue;
  const attack=actor.attack,opponent=game.teams[1-actor.side],p=attack.t;
  if(p>.3&&p<.87){
   const gap=opponent.x-actor.x;
   actor.face=gap>=0?1:-1;
   if(Math.abs(gap)>73)actor.x+=Math.sign(gap)*Math.min(Math.abs(gap)-73,130*dt);
   if(p>.60)opponent.stun=Math.max(opponent.stun,.10);
  }
  if(p>.39&&actor.jChairCue===0){actor.jChairCue=1;cameraMode='track';spawnRing(actor.x,FLOOR-130,'#f1526d',35);}
  if(p>.70&&actor.jChairCue===1){actor.jChairCue=2;cameraMode='push';shake=Math.max(shake,7);}
 }
 return originalUpdate(dt);
};
// J-Styles uses four actual purpose-built animation poses, not a reused kick-sheet.
const originalDraw=drawFighter;
drawFighter=function(f,t){
 const person=activeWho(f);if(person?.id!==ID)return originalDraw(f,t);
 const a=f.attack,phase=a?Math.max(0,Math.min(1,a.t/Math.max(.1,a.duration))):0;
 let pose=0;
 if(a?.jChairFinisher){pose=phase<.20?0:phase<.47?1:phase<.78?2:3;}
 else if(a?.jChairSpecial){pose=phase<.20?0:phase<.75?1:3;}
 else if(a?.kind==='punch'||a?.kind==='special')pose=1;
 else if(a?.kind==='kick'||a?.kind==='highkick'||a?.kind==='lowkick')pose=2;
 else if(a?.kind==='finish')pose=3;
 else if(f.stun>.12||f.hp[f.active]<=0)pose=2;
 const img=sprites[`${ID}_${pose}`];if(!img?.complete||!img.naturalWidth)return originalDraw(f,t);
 const by=FLOOR+f.y,ground=FLOOR+8;
 ctx.save();ctx.fillStyle='rgba(1,4,18,.38)';ctx.beginPath();ctx.ellipse(f.x,ground,76,13,0,0,Math.PI*2);ctx.fill();ctx.restore();
 ctx.save();ctx.translate(f.x,by);
 if(f.face===-1)ctx.scale(-1,1);
 if(a?.jChairFinisher){
  ctx.shadowColor='#f13f74';ctx.shadowBlur=32;
  const ring=.6+.5*Math.sin(t*16);ctx.strokeStyle=`rgba(255,79,124,${ring})`;ctx.lineWidth=5;
  ctx.beginPath();ctx.ellipse(0,-142,130+phase*52,145+phase*36,0,0,Math.PI*2);ctx.stroke();
 }
 if(f.tagFx>0){ctx.strokeStyle='#ffe277';ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,-150,130+f.tagFx*35,0,Math.PI*2);ctx.stroke();}
 const height=304,width=height*img.naturalWidth/img.naturalHeight;
 // Wind-up and impact pose tweaks provide motion even with cut-out sprites.
 if(a?.jChairFinisher){
  ctx.translate(phase<.47?Math.sin(phase*10)*9:phase<.78?33*phase:0,phase<.78?0:-12*Math.sin(phase*6));
  ctx.rotate(phase>.48&&phase<.80?-.075:0);
 }
 ctx.drawImage(img,-width/2,-height,width,height);ctx.restore();
 if(a?.jChairFinisher){
  ctx.save();const alpha=Math.min(1,Math.max(0,(phase-.16)*3));ctx.globalAlpha=alpha;ctx.font='900 24px Impact,Arial';ctx.textAlign='center';ctx.shadowBlur=14;ctx.shadowColor='#ff174c';ctx.fillStyle='#ffe36e';
  ctx.fillText(phase<.51?'CHAIR FEINT!':phase<.78?'STUNNER DROP!':'LAST CALL!',f.x,FLOOR+f.y-323);
  ctx.restore();
 }
};
// Align the dossier title and describe J-Styles' special move clearly.
const oldStyles=showStyles;
showStyles=function(){oldStyles();const title=document.querySelector('.panel h2');if(title&&/FIGHTER WEAPON/.test(title.textContent))title.textContent=`${roster.length} FIGHTERS • WEAPON & POWER DOSSIERS`;};
const oldMenu=showMenu;
showMenu=function(){oldMenu();const btn=[...document.querySelectorAll('[data-go]')].find(x=>x.dataset.go==='styles');if(btn)btn.textContent=`⚔ ${roster.length} UNIQUE WEAPONS, STANCES & COMBOS`;};
showMenu();
window.__JSTYLES_TEST__={get roster(){return roster.find(x=>x.id==='jstyles')},get style(){return FIGHT_STYLES.jstyles},get sprite(){return sprites.jstyles_0},get game(){return game},action,showStyles};
})();